// ─── File: CommitProtocolsDemo.java ───
// Runnable demo: 2PC (with coordinator-crash blocking) vs Saga (local commits).

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class CommitProtocolsDemo {

    private static final Logger log = Logger.getLogger("commit");

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        BigDecimal amount = new BigDecimal("50000");

        log.info("===== TWO-PHASE COMMIT: happy path =====");
        XaParticipant rajesh = new XaParticipant(new AccountResource("SAV2001", new BigDecimal("1000000")), amount.negate());
        XaParticipant priya  = new XaParticipant(new AccountResource("CUR3001", new BigDecimal("250000")), amount);
        TwoPhaseCommitCoordinator coord = new TwoPhaseCommitCoordinator(List.of(rajesh, priya));
        coord.runTransaction(false);   // no crash

        log.info("===== TWO-PHASE COMMIT: coordinator crashes after unanimous YES =====");
        XaParticipant r2 = new XaParticipant(new AccountResource("SAV2001", new BigDecimal("1000000")), amount.negate());
        XaParticipant p2 = new XaParticipant(new AccountResource("CUR3001", new BigDecimal("250000")), amount);
        TwoPhaseCommitCoordinator coord2 = new TwoPhaseCommitCoordinator(List.of(r2, p2));
        coord2.runTransaction(true);   // crash → participants stuck locked

        log.info("===== SAGA: local commits + compensation (no global locks) =====");
        SagaTransfer saga = new SagaTransfer(
                new AccountResource("SAV2001", new BigDecimal("1000000")),
                new AccountResource("CUR3001", new BigDecimal("250000")));
        saga.transfer(amount, false);   // success
        saga.transfer(new BigDecimal("30000"), true);   // credit fails → compensate
    }
}

// ─── model/AccountResource.java ───
class AccountResource {
    final String id; BigDecimal balance; String lockState = "FREE";
    AccountResource(String id, BigDecimal balance) { this.id = id; this.balance = balance; }
}

// ─── twopc/Vote.java ───
enum Vote { YES, NO }

// ─── twopc/XaParticipant.java ───
class XaParticipant {
    private static final Logger log = Logger.getLogger("commit");
    private final AccountResource account; private final BigDecimal delta;
    private BigDecimal pending;
    XaParticipant(AccountResource account, BigDecimal delta) { this.account = account; this.delta = delta; }

    // Phase 1: prepare — durably stage change, LOCK, and vote.
    Vote prepare() {
        BigDecimal next = account.balance.add(delta);
        if (next.compareTo(BigDecimal.ZERO) < 0) return Vote.NO;
        pending = next;
        account.lockState = "LOCKED";    // locks held until decision arrives
        log.info(() -> "[2PC] " + account.id + " PREPARED (LOCKED), voting YES");
        return Vote.YES;
    }
    // Phase 2: commit — apply staged change and release lock.
    void commit() {
        account.balance = pending; account.lockState = "FREE";
        log.info(() -> "[2PC] " + account.id + " COMMITTED balance=Rs." + account.balance);
    }
    void abort() { pending = null; account.lockState = "FREE"; log.warning(() -> "[2PC] " + account.id + " ABORTED"); }
    String status() { return account.id + " lock=" + account.lockState + " balance=Rs." + account.balance; }
}

// ─── twopc/TwoPhaseCommitCoordinator.java ───
class TwoPhaseCommitCoordinator {
    private static final Logger log = Logger.getLogger("commit");
    private final List<XaParticipant> participants;
    TwoPhaseCommitCoordinator(List<XaParticipant> participants) { this.participants = participants; }

    void runTransaction(boolean crashAfterVotes) {
        // Phase 1: collect votes
        boolean allYes = true;
        for (XaParticipant p : participants) if (p.prepare() == Vote.NO) allYes = false;

        if (crashAfterVotes) {
            // Coordinator dies here — decision never broadcast. Participants stay LOCKED.
            log.severe("[2PC] COORDINATOR CRASHED after unanimous YES — decision never sent");
            participants.forEach(p -> log.severe(() -> "[2PC] STUCK: " + p.status() + " (locks held INDEFINITELY)"));
            return;
        }
        // Phase 2: broadcast decision
        if (allYes) participants.forEach(XaParticipant::commit);
        else participants.forEach(XaParticipant::abort);
    }
}

// ─── saga/SagaTransfer.java ───
class SagaTransfer {
    private static final Logger log = Logger.getLogger("commit");
    private final AccountResource from; private final AccountResource to;
    SagaTransfer(AccountResource from, AccountResource to) { this.from = from; this.to = to; }

    void transfer(BigDecimal amount, boolean creditFails) {
        // Step 1: LOCAL commit in debit service — lock released immediately.
        from.balance = from.balance.subtract(amount);
        log.info(() -> "[SAGA] debit committed locally: " + from.id + " = Rs." + from.balance + " (no global lock)");
        try {
            if (creditFails) throw new RuntimeException("credit service unavailable");
            // Step 2: LOCAL commit in credit service.
            to.balance = to.balance.add(amount);
            log.info(() -> "[SAGA] credit committed locally: " + to.id + " = Rs." + to.balance);
        } catch (RuntimeException e) {
            // Compensating transaction — no coordinator, no held locks.
            from.balance = from.balance.add(amount);
            log.warning(() -> "[SAGA] credit failed → COMPENSATE: " + from.id + " restored to Rs." + from.balance);
        }
    }
}

// ─── BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tH:%1$tM:%1$tS %2$-7s %3$s%n",
                new Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
